CREATE TABLE public.epi_setores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL, nome text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (empresa_id, nome));
CREATE TABLE public.epi_setor_itens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL, setor_id uuid NOT NULL REFERENCES public.epi_setores(id) ON DELETE CASCADE, epi_id uuid NOT NULL REFERENCES public.epi_itens(id) ON DELETE CASCADE, quantidade integer NOT NULL DEFAULT 1, UNIQUE (setor_id, epi_id));
CREATE TABLE public.epi_funcionario_setor (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL, usuario_id uuid NOT NULL, setor_id uuid NOT NULL REFERENCES public.epi_setores(id) ON DELETE CASCADE, UNIQUE (empresa_id, usuario_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.epi_setores, public.epi_setor_itens, public.epi_funcionario_setor TO authenticated;
GRANT ALL ON public.epi_setores, public.epi_setor_itens, public.epi_funcionario_setor TO service_role;
ALTER TABLE public.epi_setores ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.epi_setor_itens ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.epi_funcionario_setor ENABLE ROW LEVEL SECURITY;
CREATE POLICY "epi_setores tenant" ON public.epi_setores FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM ponto_empresas e WHERE e.id = epi_setores.empresa_id AND e.estabelecimento_id = get_auth_user_estabelecimento_id())) WITH CHECK (EXISTS (SELECT 1 FROM ponto_empresas e WHERE e.id = epi_setores.empresa_id AND e.estabelecimento_id = get_auth_user_estabelecimento_id()));
CREATE POLICY "epi_setor_itens tenant" ON public.epi_setor_itens FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM ponto_empresas e WHERE e.id = epi_setor_itens.empresa_id AND e.estabelecimento_id = get_auth_user_estabelecimento_id())) WITH CHECK (EXISTS (SELECT 1 FROM ponto_empresas e WHERE e.id = epi_setor_itens.empresa_id AND e.estabelecimento_id = get_auth_user_estabelecimento_id()));
CREATE POLICY "epi_funcionario_setor tenant" ON public.epi_funcionario_setor FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM ponto_empresas e WHERE e.id = epi_funcionario_setor.empresa_id AND e.estabelecimento_id = get_auth_user_estabelecimento_id())) WITH CHECK (EXISTS (SELECT 1 FROM ponto_empresas e WHERE e.id = epi_funcionario_setor.empresa_id AND e.estabelecimento_id = get_auth_user_estabelecimento_id()));